"""Actual R1-negative surfaces and optimizer history, with unchanged view scale."""
from pathlib import Path
import json,hashlib,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d.art3d import Poly3DCollection
r=Path(__file__).resolve().parent;work=r.parent;source=work/'qualified-dilation-001/carrier-r1-negative-001';case=r/'r1-negative-001';paths=[source/'decoded-001/candidate.npz',case/'decoded-001/candidate.npz'];meta=json.loads((case/'assessment.json').read_text());audits=[json.loads((p/'material-feature-audit.json').read_text())for p in [source,case]];data=[np.load(p)for p in paths];v=data[0]['vertices'];f=data[0]['triangles'];edge=audits[0]['most_reentrant_edges'][0]['vertices'];center=v[edge].mean(0);mask=np.linalg.norm(v-center,axis=1)<.055;faces=f[np.all(mask[f],axis=1)];tri=v[faces];normal=np.cross(tri[:,1]-tri[:,0],tri[:,2]-tri[:,0]).sum(0);normal/=np.linalg.norm(normal);azim=float(np.degrees(np.arctan2(normal[1],normal[0])))-25
fig=plt.figure(figsize=(16,6.8),facecolor='#f7f9fc')
for i,z in enumerate(data):
 ax=fig.add_subplot(1,3,i+1,projection='3d');t=(z['vertices'][faces]-center)*1000;n=np.cross(t[:,1]-t[:,0],t[:,2]-t[:,0]);n/=np.linalg.norm(n,axis=1)[:,None];shade=.55+.4*np.abs(n@np.array([.3,-.4,.866]));colors=np.clip(np.array([.18,.61,.66])[None,:]*shade[:,None],0,1);ax.add_collection3d(Poly3DCollection(t,facecolors=colors,edgecolors='#173645',linewidths=.35));ax.set(xlim=(-55,55),ylim=(-55,55),zlim=(-55,55),xlabel='Δx (µm)',ylabel='Δy (µm)',zlabel='Δz (µm)');ax.set_box_aspect((1,1,1));ax.view_init(elev=25,azim=azim);ax.set_title(['Original rounded surface','Direct angle optimization'][i],fontsize=13,fontweight='bold',pad=14);ax.set_facecolor('#f7f9fc')
ax=fig.add_subplot(1,3,3);history=meta['history'];ax.plot([0]+[h['iteration']for h in history],[meta['initial_patch_maximum_degrees']]+[h['maximum_reentrant_degrees']for h in history],color='#137d87',lw=2);ax.axhline(45,color='#b54436',ls='--',label='45° acceptance threshold');ax.set(xlabel='Optimizer iteration',ylabel='Maximum turn in optimized patch (degrees)',ylim=(40,70));ax.grid(alpha=.18);ax.legend(frameon=False,loc='upper right');ax.set_title('Measured optimizer history',fontsize=13,fontweight='bold');ax.set_facecolor('#f7f9fc')
fig.suptitle('R1 negative — direct control of the remaining creases',x=.055,ha='left',fontsize=20,fontweight='bold',y=.98);fig.text(.055,.89,'Actual triangles · same camera and scale · no displacement exaggeration',fontsize=12,color='#475569')
before=-audits[0]['most_reentrant_edges'][0]['normal_turn_degrees'];after=-audits[1]['most_reentrant_edges'][0]['normal_turn_degrees'];fig.text(.065,.105,f'Full boundary maximum: {before:.2f}° → {after:.2f}°\nZero edges above 45° in the independent audit',fontsize=12,fontweight='bold',color='#173645');fig.text(.49,.105,f'{meta["changed_vertices"]} vertices moved; triangle indices unchanged\nComplete symmetric surface bound: {1000*meta["complete_symmetric_surface_bound_mm"]:.3f} µm',fontsize=12,color='#173645');fig.text(.065,.025,'Full independent embedding and original-void containment passed. Cavity geometry only; mechanical convergence is a subsequent stage.',fontsize=10,color='#475569');fig.subplots_adjust(left=.035,right=.98,top=.82,bottom=.23,wspace=.22);out=r/'r1-direct-optimization.png';fig.savefig(out,dpi=150);plt.close(fig)
(r/'image.json').write_text(json.dumps(dict(inputs=[dict(path=str(p.relative_to(work)),sha256=hashlib.sha256(p.read_bytes()).hexdigest())for p in paths],image_sha256=hashlib.sha256(out.read_bytes()).hexdigest(),center_mm=center.tolist(),triangles_shown=len(faces),camera_elevation=25,camera_azimuth=azim),indent=2)+'\n');print(out)
